import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

// GELU (tanh approximation):
//   y = 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
//     = x * sigmoid(2 * sqrt(2/pi) * (x + 0.044715 * x^3))
// sigmoid(2z) = 1 - 1 / (exp(2z) + 1), exp(2z) = 2^(2*log2(e)*z)
.visible .entry gelu_tanh_fwd(
    .param .u64 gelu_in,
    .param .u64 gelu_out,
    .param .u32 gelu_n
)
{
    .reg .b32 %r_bid;
    .reg .b32 %r_tid;
    .reg .b32 %r_idx;
    .reg .b32 %r_n;
    .reg .b64 %rd_in;
    .reg .b64 %rd_out;
    .reg .b64 %rd_off;
    .reg .b64 %rd_addr;
    .reg .f32 %f_x;
    .reg .f32 %f_x2;
    .reg .f32 %f_x3;
    .reg .f32 %f_t;
    .reg .f32 %f_z;
    .reg .f32 %f_w;
    .reg .f32 %f_e;
    .reg .f32 %f_d;
    .reg .f32 %f_r;
    .reg .f32 %f_s;
    .reg .f32 %f_y;
    .reg .pred %p_oob;

    ld.param.u64 %rd_in, [gelu_in];
    ld.param.u64 %rd_out, [gelu_out];
    ld.param.u32 %r_n, [gelu_n];

    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_tid, %tid.x;
    mad.lo.u32 %r_idx, %r_bid, 256, %r_tid;

    // Bounds check for potentially partial final block.
    setp.ge.u32 %p_oob, %r_idx, %r_n;
    @%p_oob bra $L_done;

    mul.wide.u32 %rd_off, %r_idx, 4;
    add.s64 %rd_addr, %rd_in, %rd_off;
    ld.global.f32 %f_x, [%rd_addr];

    // t = x + 0.044715 * x^3
    mul.f32 %f_x2, %f_x, %f_x;
    mul.f32 %f_x3, %f_x2, %f_x;
    fma.rn.f32 %f_t, %f_x3, 0.044715, %f_x;
    // z = sqrt(2/pi) * t
    mul.f32 %f_z, %f_t, 0.79788456080286536;
    // w = 2 * log2(e) * z
    mul.f32 %f_w, %f_z, 2.88539008177792681;
    // e = 2^w = exp(2z)
    ex2.approx.f32 %f_e, %f_w;
    // sig = 1 - 1/(e+1)
    add.f32 %f_d, %f_e, 1.0;
    div.full.f32 %f_r, 1.0, %f_d;
    sub.f32 %f_s, 1.0, %f_r;
    // y = x * sig
    mul.f32 %f_y, %f_x, %f_s;

    add.s64 %rd_addr, %rd_out, %rd_off;
    st.global.f32 [%rd_addr], %f_y;

$L_done:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("gelu_tanh_fwd")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        x = x.contiguous()
        out = torch.empty_like(x)
        n = x.numel()
        module = _get_ptx_module()
        grid_x = (n + 255) // 256
        module.launch(
            "gelu_tanh_fwd",
            grid=(grid_x, 1, 1),
            block=(256, 1, 1),
            arguments=[x, out, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

